+#!/bin/bash
+set -euo pipefail
+cd /testbed
+
+
+export PATH="/opt/node-20/bin:$PATH"
+
+
+if [ ! -x node_modules/.bin/jest ]; then
+  npx --yes yarn@1.22.22 install --frozen-lockfile --ignore-engines --non-interactive
+fi
+
+case "${1:-}" in
+  base)
+    npx jest --testPathPattern="packages/aws-lambda-graphql/src/__tests__/(ApolloClient\.integration|withFilter)\.test\.ts$" --runInBand --no-coverage
+    ;;
+  new)
+    npx jest --testPathPattern="packages/aws-lambda-graphql/src/__tests__/Server\.test\.ts$" --testNamePattern="echoes requested websocket subprotocol|does not add websocket subprotocol" --runInBand --no-coverage
+    ;;
+  *)
+    echo "usage: $0 base|new"
+    exit 2
+    ;;
+esac

